arguments.command:
python3 -c "
from openpyxl import load_workbook
wb = load_workbook('budget.xlsx', data_only=False)
ws = wb['Budget']
for r in range(2, 25):
    vals = []
    for c in range(1, 4):
        cell = ws.cell(row=r, column=c)
        if cell.value is not None:
            vals.append(f'{cell.coordinate}={cell.value!r}')
    if vals:
        print(' | '.join(vals))
"
